import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"小畜","description":"焦氏易林注 - 小畜","frontmatter":{"title":"小畜","description":"焦氏易林注 - 小畜"},"headers":[],"relativePath":"classics/jiaoyilin/009.md","filePath":"classics/jiaoyilin/009.md"}'),l={name:"classics/jiaoyilin/009.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="小畜" tabindex="-1">小畜 <a class="header-anchor" href="#小畜" aria-label="Permalink to “小畜”">​</a></h1><h3 id="小畜-1" tabindex="-1">小畜 <a class="header-anchor" href="#小畜-1" aria-label="Permalink to “小畜”">​</a></h3><h3 id="小畜之乾" tabindex="-1">小畜之乾 <a class="header-anchor" href="#小畜之乾" aria-label="Permalink to “小畜之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>東遇虎蛇，牛馬驚奔。道絕不通，商困無功。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦象。離為東，乾虎巽蛇，故曰東遇虎蛇。離牛乾馬，伏震為驚奔、為道，伏坎，故不通。巽為商賈。○虵，依汲古，宋元本作地。</p><h3 id="小畜之坤" tabindex="-1">小畜之坤 <a class="header-anchor" href="#小畜之坤" aria-label="Permalink to “小畜之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>子鋤獲麟，春秋作經。元聖將終，尼父悲心。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>依汲古《訟》之《同人》校，此用《小畜》象。○經，宋元本作元，元聖作陰聖。汲古下三句作&quot;庶士開元，豪雄爭名，都邑倍遊&quot;，茲從宋元本。</p><h3 id="小畜之屯" tabindex="-1">小畜之屯 <a class="header-anchor" href="#小畜之屯" aria-label="Permalink to “小畜之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>灼火泉源，釣魚山巔。魚不可得，火不肯然。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《此》之《屯》。○灼，依汲古，宋元作取。</p><h3 id="小畜之蒙" tabindex="-1">小畜之蒙 <a class="header-anchor" href="#小畜之蒙" aria-label="Permalink to “小畜之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>機關不便，不能出言。精誠不通，為人所冤。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坎為機關，坤閉故不便，故言不能出。震為言、為出。坎為心、為精誠，坤閉故不通。坎為冤，震為人。</p><h3 id="小畜之需" tabindex="-1">小畜之需 <a class="header-anchor" href="#小畜之需" aria-label="Permalink to “小畜之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>故室舊廬，稍蔽紱組。不如新巢，可以樂居。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>坎為宮室、為廬，乾為故舊。伏坤為帛、為紱組，坎為蔽，離為巢、為新。兌悅故曰樂居。○蔽紱組，從汲古，元本作&quot;稍弊且除&quot;，宋作&quot;且徐&quot;。可以，汲古、宋元本作可治，依局本。</p><h3 id="小畜之訟" tabindex="-1">小畜之訟 <a class="header-anchor" href="#小畜之訟" aria-label="Permalink to “小畜之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>蜲蛇循流，東求大魚。預且舉網，庖人歌謳。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>巽為蛇、為魚。蜲蛇，行貌。離位東，坎為流水，乾大，故曰大魚。預且，宋漁人名。《莊子》：&quot;神龜見夢於元君不能避餘且之網&quot;。離為網，離火故曰庖人。伏震為歌謳。</p><h3 id="小畜之師" tabindex="-1">小畜之師 <a class="header-anchor" href="#小畜之師" aria-label="Permalink to “小畜之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>鑿山通道，南至嘉國。周公祝祖，襄適荊楚。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>艮覆，故曰鑿山。震為大塗、為通，故曰通道。震為南，坤為國，震為周、為公、為祝、為荊楚、為諸侯，故曰襄適荊楚。《左傳昭七年》：&quot;公將往楚，夢襄公祖梓慎曰：襄公之適楚也，夢周公祖而行&quot;。按：《詩》雲&quot;仲山甫出祖&quot;，《毛傳》：&quot;祖，祭道神也&quot;，周公祝祖者，謂襄公適楚，夢周公祖而行也。○祖，依宋本，汲古作&quot;周公所祝&quot;，非。</p><h3 id="小畜之比" tabindex="-1">小畜之比 <a class="header-anchor" href="#小畜之比" aria-label="Permalink to “小畜之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>鵲近卻縮，不見頭目。日以困急，不能自復。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為鵲，坤為近、為退，故曰縮卻。縮，退也，言鵲近人而避也。離為目，乾為首，離乾伏，故不見。艮為時，坎為困，震為復，震覆故不能復。○近，從宋元本，汲古作足。以，從宋元本，汲古作久。</p><h3 id="小畜之小畜" tabindex="-1">小畜之小畜 <a class="header-anchor" href="#小畜之小畜" aria-label="Permalink to “小畜之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>白鳥銜餌，鳴呼其子。斡枝張翅，來從其母。伯仲叔季，元賀舉手。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>巽為白，離為鳥，兌口為銜，巽為餌。通《豫》。震為鳴、為子、為枝、為羽、為斡、為張。坤為母，震為從、為伯，互坎為仲，艮為叔季、為手。元賀者，賀元日也。舉手，揖也。○元，依汲古，宋元本作尤。</p><h3 id="小畜之履" tabindex="-1">小畜之履 <a class="header-anchor" href="#小畜之履" aria-label="Permalink to “小畜之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>五舌啄難，各自有言。異國殊俗，使心迷惑，所求不得。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>互巽，卦數五，兌為舌，故曰五舌，舌多故啄難。正反兌相對，故各自有言。通《謙》。坤為國、為俗，艮亦為國，正覆艮，故曰異國殊俗。坤為迷，坎為心，故曰使心迷惑。艮為求，坤喪故不得。○二三句皆用覆象。</p><h3 id="小畜之泰" tabindex="-1">小畜之泰 <a class="header-anchor" href="#小畜之泰" aria-label="Permalink to “小畜之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>天門開闢，牢戶寥廓。桎梏解脫，拘囚縱釋。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>乾坤皆為門戶，而乾居戊亥，故曰天門。《乾鑿度》雲&quot;乾為天門&quot;，《莊子庚桑楚》雲&quot;天門者，無有也&quot;，萬物出乎無有，本之《易》也。互震故曰開闢。坤閉故曰牢戶、曰桎梏、曰拘囚。震為人，人閉坤中，故有此象。而震為通達，故得解脫縱釋也。○囚，從宋元本，汲古訛困。○坎為牢、為桎梏，坤閉，故與坎同象。此亦失傳之象。</p><h3 id="小畜之否" tabindex="-1">小畜之否 <a class="header-anchor" href="#小畜之否" aria-label="Permalink to “小畜之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>堅冰黃鳥，啼哀悲愁。數驚鷙鳥，雛為我憂。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮為堅，乾為水，坤為黃，艮為鳥，伏震為啼、為驚。坤為悲愁，艮為鷙鳥，兌為雛，兌覆故憂。○啼，從汲古，宋本誤當，元本誤常。鳥、雛，從宋元本，汲古作鷂、飄。悲愁，宋本誤愁悲，失韻。</p><h3 id="小畜之同人" tabindex="-1">小畜之同人 <a class="header-anchor" href="#小畜之同人" aria-label="Permalink to “小畜之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>日走月步，趣不同舍。夫妻反目，主君失居。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。離日坎月，震為步、為趣、為夫，巽為妻，初至三兩半離相對，故曰反目。震為主君，艮為居，艮覆，故失居。《小畜》九三&quot;夫妻反目&quot;，即以兩半離相對為反目也。</p><h3 id="小畜之大有" tabindex="-1">小畜之大有 <a class="header-anchor" href="#小畜之大有" aria-label="Permalink to “小畜之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>金牙鐵齒，西王母子。無有禍殃，候舍涉道，到來不久。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>兌為齒牙，乾為金鐵，兌位西，乾王坤母，故曰西王母子。坤為禍殃，坤伏故無。候舍涉道，未詳，疑有訛字。○禍，從汲古，宋元本作患。候，宋元本作扶，汲古作候。到，從宋元本，汲古作別。</p><h3 id="小畜之謙" tabindex="-1">小畜之謙 <a class="header-anchor" href="#小畜之謙" aria-label="Permalink to “小畜之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>式微式微，憂禍相絆。隔以巖山，室家分散。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>式微，《邶詩》篇名，坤柔，故曰式微。坎為憂，伏巽繩，故曰絆。艮為巖山、為室家，正反艮故曰分散。○絆，從汲古，宋元本作半，非。式微式微胡不歸，黎臣怨其君不歸，故曰絆。又震為歸，故知半非。又式微，元本訛拭牧，依宋本、汲古。</p><h3 id="小畜之豫" tabindex="-1">小畜之豫 <a class="header-anchor" href="#小畜之豫" aria-label="Permalink to “小畜之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>眾神聚集，相與議語。南國虐亂，百姓勞苦。興師征伐，更立賢主。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>解詳《屯》之《節》，《節》中爻艮震與《豫》體同。○聚集，從宋元本，汲古作集聚。更，汲古作別，依宋元本。</p><h3 id="小畜之隨" tabindex="-1">小畜之隨 <a class="header-anchor" href="#小畜之隨" aria-label="Permalink to “小畜之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>虎狼爭食，禮義不行。兼吞其國，齊魯無王。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為虎狼，初四正反艮，震口，故曰爭食。坤為禮義，否初往上坤形毀，艮止，故不行。艮為國，兌口，故曰吞。巽齊兌魯，震為王，正反震，故曰無王。言列國互相兼併，周王不能制止也。○義、行、魯，從宋元本，汲古作讓、作能、作晉。王，各本多作主，豈知行與王韻，主雖震象，韻不協，依汲古《比》之《艮》校。</p><h3 id="小畜之蠱" tabindex="-1">小畜之蠱 <a class="header-anchor" href="#小畜之蠱" aria-label="Permalink to “小畜之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>寄生無根，如過浮雲。本立不固，斯須落去，更為枯樹。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>《漢書東方朔傳》：&quot;著樹為寄生&quot;，師古曰：&quot;寄生者，芝菌之類，為雨淋著樹而生&quot;，故曰無根。上艮形似寄生，巽下斷故無根。互大坎故曰浮雲。巽下斷，故本不固，故落去。艮為時、為待，故曰斯須。言寄生頃刻即枯落也。離為枯。丁據《詩正義》以蔦釋寄生，非蔦固名寄生，然非斯須落去之物，與此不合。</p><h3 id="小畜之臨" tabindex="-1">小畜之臨 <a class="header-anchor" href="#小畜之臨" aria-label="Permalink to “小畜之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>子啼索哺，母行求食。反見空巢，訾我長息。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《同人》。○求，依宋元，汲古作取。訾我，宋元作訾弋，汲古作紫弋，依《乾》之《同人》校。</p><h3 id="小畜之觀" tabindex="-1">小畜之觀 <a class="header-anchor" href="#小畜之觀" aria-label="Permalink to “小畜之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>駕駟逐狐，輪掛荊棘。車不結轍，公子無得。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>伏震為駕、為駟、為逐，艮為狐。伏乾為圜、為輪，震為荊棘，艮止，故曰掛。坤為車，艮為道路、為轍，坤閉艮止，故曰車不結轍，言輪不動而無轍跡也。震為公子，坤虛，故無所得。正伏象雜用。</p><h3 id="小畜之噬嗑" tabindex="-1">小畜之噬嗑 <a class="header-anchor" href="#小畜之噬嗑" aria-label="Permalink to “小畜之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>方喙廣口，仁智聖厚。釋解倒懸，家國大安。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>通《井》。兌為口，艮為喙，震為仁，坎為聖、為智，艮為厚，井巽繩為懸，兌為倒巽，故曰倒懸。震為解釋，艮為國家、為安。○家，各本皆作唐，依《井》之《恆》校。</p><h3 id="小畜之賁" tabindex="-1">小畜之賁 <a class="header-anchor" href="#小畜之賁" aria-label="Permalink to “小畜之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>駕福乘喜，東至嘉國。戴慶南行，移居安宅。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為駕、為乘、為福喜、為東、為嘉，艮為國、為戴，震為慶，故曰戴慶。離為南，故曰南行。艮為宅、為居、為安。○東至嘉國，移居安宅。依汲古，宋元本作&quot;來至家國，離我安居&quot;，失韻，非。</p><h3 id="小畜之剝" tabindex="-1">小畜之剝 <a class="header-anchor" href="#小畜之剝" aria-label="Permalink to “小畜之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>孔鯉伯魚，北至高奴。木馬金車，駕遊大都。王母送我，騋牝字駒。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤為鯉、為魚，中虛，故為孔。坤位北，艮為奴，艮山在上，故曰高奴。高奴，地名。《項羽傳》：&quot;董醫王上郡高奴&quot;是也。坤為馬，艮木，故曰木馬。坤為車，艮金，故曰金車。坤為都，伏乾為大，故曰大都。乾王坤母，坤我，故曰王母送我。坤為馬、為牝，故曰騋牝字駒。《史記平準書》：&quot;乘字牝者不得集會&quot;，字，乳也，即牝也。○字，依宋元本，汲古作牸，字牸同。○坤北艮金確證。</p><h3 id="小畜之復" tabindex="-1">小畜之復 <a class="header-anchor" href="#小畜之復" aria-label="Permalink to “小畜之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>三足無頭，不知所之。心狂精傷，莫使為明，不見日光。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震足數三，乾為頭，乾伏，故曰三足無頭。震為之，坤迷，故不知所之。震為狂、為精神，坤為傷，故曰精傷。坤黑，故不明。乾為日，乾伏，故不見。</p><h3 id="小畜之無妄" tabindex="-1">小畜之無妄 <a class="header-anchor" href="#小畜之無妄" aria-label="Permalink to “小畜之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>騋牝龍身，日馭三千。南止蒼梧，與福為婚。道里夷易，安全無忌。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為馬、為龍，巽為牝，艮為身，乾為日，震為馭驅也、為三千、為南、為蒼梧。艮止震巽為夫婦，故曰婚。艮為道、為裡，震為夷易，艮安震樂，故無忌。○馭，依宋本，元本訛取，汲古訛越。由二本訛字觀之，似當為趣。</p><h3 id="小畜之大畜" tabindex="-1">小畜之大畜 <a class="header-anchor" href="#小畜之大畜" aria-label="Permalink to “小畜之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>辰次降婁，王駕巡狩。廣佑施惠，安國無憂。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>降婁，即奎婁，戍分艮先天位戌，故曰辰次降婁。乾為王，震為駕、為巡狩。乾為廣、為施惠，艮為安、為國，震樂，故無憂。○狩，依汲古，宋元本作時，非。</p><h3 id="小畜之頤" tabindex="-1">小畜之頤 <a class="header-anchor" href="#小畜之頤" aria-label="Permalink to “小畜之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>望幸不到，文章未就。王子逐走，馬騎銜傷。佚跡不得，曷其有常。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>蔡邕獨斷雲：&quot;天子所至，輒有賞賜，故曰幸&quot;，言人民冀幸得賞也。艮為望，震為王、為行、為幸，艮止，故不到。坤為文章，艮止，故不就。震為王子、為走、為馬、為騎、為口，故為銜。坤傷，故曰銜傷。震為跡。佚，避也，言遁跡不得也。○文章未就，從宋本增，汲古及各本皆無。佚，從宋本，汲古作失，非。屈子遠遊，離人群而遁佚是其義。○艮為望確證。</p><h3 id="小畜之大過" tabindex="-1">小畜之大過 <a class="header-anchor" href="#小畜之大過" aria-label="Permalink to “小畜之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>中原有菽，以待饔食。飲御諸友，所求大得。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>乾為郊，故曰中原。下巽為菽，兌為飲食、為友。伏艮為求。</p><h3 id="小畜之坎" tabindex="-1">小畜之坎 <a class="header-anchor" href="#小畜之坎" aria-label="Permalink to “小畜之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>亂茅縮酒，靈巫拜禱。神怒不許，瘁愁憂苦。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>伏巽為茅，坎為酒，祭時灌酒茅上曰縮酒。縮，漏也。《井》九三雲，甕敝漏，巽為漏也。伏兌為巫、為禱。艮為拜，震為神、為怒。坎為勞瘁愁苦。○愁憂，從宋元本，汲古作盡愁。</p><h3 id="小畜之離" tabindex="-1">小畜之離 <a class="header-anchor" href="#小畜之離" aria-label="Permalink to “小畜之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>李華再實，鴻卵降集。仁哲以興，蔭國受福。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《訟》。</p><h3 id="小畜之鹹" tabindex="-1">小畜之鹹 <a class="header-anchor" href="#小畜之鹹" aria-label="Permalink to “小畜之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>源出陵足，行於山趾。不為暴害，民得安處。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。坤為水，艮陵。震為足、為趾，上山下足，水從山出，故曰源出陵足，行於山趾。坤為害，艮安，故不害。坤為民。○源，汲古作原，依宋元本。處，宋本、汲古作居，從元本。</p><h3 id="小畜之恆" tabindex="-1">小畜之恆 <a class="header-anchor" href="#小畜之恆" aria-label="Permalink to “小畜之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>客入其門，奔走東西。童女不織，士棄耕畝。暴骨千里，歲饑民苦。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>通《益》。震為客，艮為門，巽入，震東，兌西，震為奔走，兌少，故曰童女。巽為織，艮止，故不織。震為士、為耕，坤為畝，艮止，故不耕。兌為骸骨，坤為千里，艮火在上，故曰暴骨千里。坤為歲、為民、為飢。○飢，依汲古，宋元本作寒。</p><h3 id="小畜之遯" tabindex="-1">小畜之遯 <a class="header-anchor" href="#小畜之遯" aria-label="Permalink to “小畜之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>天子所予，福祿常在。以永康寧，不憂危殆。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為天、為福祿，艮安故不危。○汲古無第三句，依宋元本。</p><h3 id="小畜之大壯" tabindex="-1">小畜之大壯 <a class="header-anchor" href="#小畜之大壯" aria-label="Permalink to “小畜之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>蝗食我稻，驅不可去。實穗無有，但見空藳。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>伏巽為蝗，兌為食，震為稻、為驅，艮為果窳、為實穗，艮伏，故無有，坤虛，故曰空藳。○藳，汲古作槁，依宋元。</p><h3 id="小畜之晉" tabindex="-1">小畜之晉 <a class="header-anchor" href="#小畜之晉" aria-label="Permalink to “小畜之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>牛驥同槽，郭氏以亡。國破空虛，君奔走逃。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為槽。坤牛坎馬，皆與艮連體，故曰同槽。《說文》：&quot;槽，馬食器也&quot;。艮為郭，坤亡，故曰郭氏以亡。郭，國名，為齊所滅。坤為國、為空虛，坎破，故曰國破。乾為君，乾伏，故曰君逃。○槽，從宋本，汲古作堂，以與亡韻，豈知槽與逃韻。以，從汲古，宋元本作已。郭，國名，為齊所滅，見胡傳。</p><h3 id="小畜之明夷" tabindex="-1">小畜之明夷 <a class="header-anchor" href="#小畜之明夷" aria-label="Permalink to “小畜之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>狗無前足，陰謀叛北。為身害賊，何以安息。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>艮為狗，初爻陽，故曰無前足。坎為謀、為伏，故曰陰謀。震為反、為叛，坤為北、為身、為害，坎為賊，震行，故不息。○害賊，從元本，宋本作賊害，不韻。叛，汲古、宋元作其，依局本。</p><h3 id="小畜之家人" tabindex="-1">小畜之家人 <a class="header-anchor" href="#小畜之家人" aria-label="Permalink to “小畜之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>兩輪自轉，南上大阪。四馬共轅，無有屯難，與禹笑言。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>通《解》。坎為輪，重坎，故曰兩輪。離為南，震為上、為阪。坎為木、為轅，震為馬，卦數四，故曰四馬共轅。坎為屯，震樂，故無有屯難。震為笑言、為王，坎勞，故曰與禹笑言。○屯，從元本，宋本、汲古作重。又宋元多&quot;鶴鳴竅穴，不離其室&quot;八字，與上文義不屬，故從汲古。</p><h3 id="小畜之睽" tabindex="-1">小畜之睽 <a class="header-anchor" href="#小畜之睽" aria-label="Permalink to “小畜之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>芽櫱生達，陽昌於外。左手執鑰，公言錫爵。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此用《小畜》伏象。伏震為芽櫱、為生達，在上，故曰昌外。艮為手、為執，震為左、為鑰、為公、為言、為爵，全用《小畜》伏象。○震為公、為爵，可解《易》。</p><h3 id="小畜之蹇" tabindex="-1">小畜之蹇 <a class="header-anchor" href="#小畜之蹇" aria-label="Permalink to “小畜之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>秋花冬萼，數被嚴霜。甲兵當庭，萬物不生。雄犬夜鳴，民擾大驚。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用《小畜》象。兌為花萼、為秋，乾為冬、為霜，離為甲兵，伏艮為庭。當庭，疑有訛字。震為萬物，兌折，故不生。艮為犬，坎夜，震為擾驚。○兌為華確證，可釋《大過》。</p><h3 id="小畜之解" tabindex="-1">小畜之解 <a class="header-anchor" href="#小畜之解" aria-label="Permalink to “小畜之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>霜降閉戶，蟄蟲隱處。不見日月，與死為伍。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《需》。</p><h3 id="小畜之損" tabindex="-1">小畜之損 <a class="header-anchor" href="#小畜之損" aria-label="Permalink to “小畜之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>身載百裡，功加四海。為文開基，武立天柱。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>坤為身、為載、為百裡、為海，震為功，數四，故曰功加四海。坤為文，艮為基，震為武，艮為天、為柱。○天，依汲古，宋元本作大。○震為武證，可解《易》。又載疑為宰。又按：《神異經》：&quot;昆侖有銅柱焉，其高入天，所謂天柱&quot;，又《列子》：&quot;共工氏觸不周之山，天柱折，地維絕&quot;，立天柱，猶植基也。</p><h3 id="小畜之益" tabindex="-1">小畜之益 <a class="header-anchor" href="#小畜之益" aria-label="Permalink to “小畜之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>禹作神鼎，伯益銜指。斧斤高閣，憧立獨坐。賣庸不讎，苦困為禍。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為王、為禹、為神、為鼎、為伯。坤為聚、為益。艮為指，震口為銜，伏兌為斧斤，艮為高閣，言斧斤閣置不用也。憧，《說文》：意不定也，《鹹》九四&quot;憧憧往來&quot;，憧立者，言徙倚不定也。又《集韻》&quot;憧，音蠢，與獃同&quot;，憧立，猶痴立也。尤與坤迷象合。震立艮坐，坤寡，故曰獨坐。庸傭同。艮為庸，巽為市易，故曰賣庸。《漢書欒布傳》：&quot;窮困賣庸&quot;註：&quot;謂受僱也&quot;，坤害故不讎。《漢書高祖紀》：&quot;每留酤讎數倍。&quot;如淳曰：&quot;讎，售也&quot;。坤為困苦、為害，丁晏雲：《呂覽》周鼎著倕而齕其指，《淮南子本經》：&quot;周鼎著倕使銜其指。&quot;註：&quot;明不當太巧也&quot;，茲作伯益，乃傳聞異詞。凡子書述故事多如此。○憧，從宋元本，汲古作幢，非。立，從汲古，宋元本作位，非。賣庸不讎，從元本，宋本作&quot;不售賣庸&quot;，汲古作&quot;賣賈不售&quot;。苦，從宋元本，汲古作讎，乃妄人將讎字移置於此。禍，從宋元本，汲古作害。</p><h3 id="小畜之夬" tabindex="-1">小畜之夬 <a class="header-anchor" href="#小畜之夬" aria-label="Permalink to “小畜之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>福祚之聚，喜至憂除。如魚逢水，長樂受喜。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾為福，重乾，故曰聚。伏坤為魚、為水，兌悅，故喜。○三四句依汲古，宋元本作&quot;如風兼雨，出車入魚&quot;。</p><h3 id="小畜之姤" tabindex="-1">小畜之姤 <a class="header-anchor" href="#小畜之姤" aria-label="Permalink to “小畜之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>蒼龍隱伏，麟鳳遠匿。寇賊同處，未得安息。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>震為蒼、為龍，震伏，故曰隱。坤文為麟鳳，坤伏，故曰匿。巽為寇賊，在內，故曰同處，消陽，故不息。○寇賊，從汲古，元本作冠履，宋本作寇來。蒼龍，從宋本，元本訛倉。</p><h3 id="小畜之萃" tabindex="-1">小畜之萃 <a class="header-anchor" href="#小畜之萃" aria-label="Permalink to “小畜之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>白鶴銜珠，夜食為明。懷安德音，身受光榮。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>伏震為鶴、為珠，兌口為銜、為食，坤為夜，艮為光明，故曰夜食為明，言得珠而明也。伏震為音，坤為身，艮貴艮光，故曰光榮。○為，從宋元本，汲古作待，非。安，從宋元本，汲古作胡，非。艮為光明，《易》光明象皆得解。○宋元本作《升》林，此必有故實。</p><h3 id="小畜之升" tabindex="-1">小畜之升 <a class="header-anchor" href="#小畜之升" aria-label="Permalink to “小畜之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>旦生夕死，名曰嬰鬼，不可得祀。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為旦、為生，坤為夕、為死，兌為嬰兒，坤為鬼，兌食為祀，坤閉，故不可得。○旦，依宋元，汲古作朝。祀，從汲古，宋本訛視。○宋元作《萃》林。</p><h3 id="小畜之困" tabindex="-1">小畜之困 <a class="header-anchor" href="#小畜之困" aria-label="Permalink to “小畜之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>行役未已，新事復起。姬薑勞苦，不得休息。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。震為行役，正反震，故不已。離為新，震起，震為姬，巽為薑，坎為勞，故不息。○休，從宋元本，汲古作安。</p><h3 id="小畜之井" tabindex="-1">小畜之井 <a class="header-anchor" href="#小畜之井" aria-label="Permalink to “小畜之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>憂患解除，喜至慶來。坐立歡忻，與樂為鄰。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《鹹》。</p><h3 id="小畜之革" tabindex="-1">小畜之革 <a class="header-anchor" href="#小畜之革" aria-label="Permalink to “小畜之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>晨風文翰，大舉就溫。昧過我邑，羿無所得。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>晨風，鸇也。通《蒙》。艮為鸇，震晨巽風，故曰晨風。坤為文，震為翰，故曰文翰。文翰，詳《大過》之《豫》。艮火，故曰就溫。坤為我、為邑，神黑，故曰昧過我邑。坤為惡，故曰羿。坤虛，故無得。陳樸園雲：《詩》：&quot;鴪彼晨風，鬱彼北林&quot;，疑齊詩作&quot;溫彼北林&quot;，故林詞屢言就溫。溫蘊通用，《雲漢》詩&quot;蘊隆蟲蟲&quot;，韓詩作鬱。蘊鬱義同。《毛傳》，鬱，積也。就溫，猶集菀耳。○文，宋元本作之，汲古作天，他本或又訛大，茲依《大過》之《豫》校。○艮鳥震翰確證，《易》多處得解。</p><h3 id="小畜之鼎" tabindex="-1">小畜之鼎 <a class="header-anchor" href="#小畜之鼎" aria-label="Permalink to “小畜之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>下田種黍，方華生齒。大雨淋集，粉澇滿甕。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坤為下、為田，震為黍、為華、為生。本卦兌為齒，坎雨坤水，故曰大雨淋集、曰紛澇。震為甕，在下承之，故滿甕。○種，依汲古，宋元作稷。方，從元本，宋、汲古作芳。生，從宋元，汲古作當。《詩》&quot;黍稷方華&quot;，林詞所本，故知宋、汲古皆誤。甕，亦從宋元本，汲古作&quot;紛榮滿壅&quot;，非。滿甕，即盈缶之義。</p><h3 id="小畜之震" tabindex="-1">小畜之震 <a class="header-anchor" href="#小畜之震" aria-label="Permalink to “小畜之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>鳥庇茂木，心樂願得。君子碌碌，見者有榖。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥、為庇，震為茂木。艮為君子，艮止，故碌碌。坎為心願，震為樂、為榖，榖，善也。○木，汲古作林，依宋元本。樂，宋元作勞，依汲古。見者有榖，宋元作見春百榖，依汲古。君子句汲古在第二句，依宋元本。</p><h3 id="小畜之艮" tabindex="-1">小畜之艮 <a class="header-anchor" href="#小畜之艮" aria-label="Permalink to “小畜之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>折臂踒足，不能進酒。祠祀闊曠，神怒不喜。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為臂，坎折。震為足，坎蹇，故曰折臂踒足。坎為酒，坎陷，故不進。震為祠祀，艮止，故闊曠。震為神、為怒、為喜，坎憂，故不喜。○震為神確證，凡《易》神象有著。</p><h3 id="小畜之漸" tabindex="-1">小畜之漸 <a class="header-anchor" href="#小畜之漸" aria-label="Permalink to “小畜之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>學靈三年，仁聖且神。明見善詳，吉喜福慶。鳱鵠知來，告我無憂。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>學靈，小兒學語也。《小畜》兌為雛、為口，正反兌相對，故曰學靈。乾為年，離卦數三，故曰三年。伏震為仁，坎為聖，震為神、為善，艮為明。祥者，兆也，吉凶之先見者也，惟明者能先見之。震為喜慶、為鳱鵠，震覆為艮，口向內，故曰來。震為言，故曰告。坤為我，坎為憂，震解，故無憂。顧千里曰：《淮南汜論訓》：&quot;乾鵠知來而不知往&quot;，鄭註《大射儀》引為鳱。愚按：《廣雅》：&quot;鳱鵠鵲也&quot;，《廣韻》：&quot;鳱鵲鳥名&quot;，陸賈雲：&quot;乾鵲噪而行人至&quot;，鳱鵠，乾鵲、乾鵠實一物，即今俗所雲喜鵲也。各本皆作鳴鳩飛來，依宋本《晉》之《艮》校。且神明見，宋元本作神明先見，依汲古。</p><h3 id="小畜之歸妹" tabindex="-1">小畜之歸妹 <a class="header-anchor" href="#小畜之歸妹" aria-label="Permalink to “小畜之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>三婦同夫，志不相思。心懷不平，至常愁悲。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>兌為婦，震數三，故曰三婦。震為夫，坎為心志，坎陷，故不平，坎憂，故愁悲也。○至常，宋元本作志常，志與上復，依汲古。</p><h3 id="小畜之豐" tabindex="-1">小畜之豐 <a class="header-anchor" href="#小畜之豐" aria-label="Permalink to “小畜之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>中田膏黍，以享王母。受福千億，所求大得。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>坎為土、為中，互大坎，故曰中田。巽為黍、為母，兌食為享，震為王，故曰以享王母。震為福、為千億，伏艮為求。○膏，從宋元本，汲古訛高。《山海經》：&quot;廣都之野，后稷葬焉，其地生膏黍&quot;，膏黍者，黏黍也。《豐》中互大坎，故曰膏。</p><h3 id="小畜之旅" tabindex="-1">小畜之旅 <a class="header-anchor" href="#小畜之旅" aria-label="Permalink to “小畜之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>陽火不災，二耕慶來。降福送喜，鼓瑟歌謳。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>離艮皆為火，中互大坎，坎水，故不為災。旁通《節》。震為耕，兌卦數二，故曰二耕，春耕、秋耕也。震為喜慶、為福、為鼓瑟、為歌謳。○不災慶來，從宋元本，汲古鼓瑟上多為我二字、歌謳下多送喜二字，為五句，然音皆不協，疑字句有訛誤，然宋元本災來韻，謳不韻，仍未愜。</p><h3 id="小畜之巽" tabindex="-1">小畜之巽 <a class="header-anchor" href="#小畜之巽" aria-label="Permalink to “小畜之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>陽明不息，君無恩德。伯氏失利，農喪其力。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>互離火故明不息。震為君、為恩德、為伯，震伏故無、故失利，巽為利也。震為農人，震伏，故喪力。○農，從宋元本，汲古作民。</p><h3 id="小畜之兌" tabindex="-1">小畜之兌 <a class="header-anchor" href="#小畜之兌" aria-label="Permalink to “小畜之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>燕雀銜茅，以生孚乳。兄弟六人，姣好悌孝。各得其願，和悅相樂。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>兌為燕雀、為銜，互巽為茅，故曰銜茅。伏坎為孚，艮為乳，震為生、為兄，艮坎為弟，坎數六，故曰兄弟六人。兌為媚、為悅，故曰姣好。互巽為順，故曰悌孝。兌悅，故曰和樂。艮為鷙鳥，凡雕鶚之屬，皆為艮象。兌與艮對，燕雀皆小鳥，故為兌象。俗象離非。○姣，從宋本，汲古作交。悌孝，汲古作孝悌，依宋元本。孝與樂韻。</p><h3 id="小畜之渙" tabindex="-1">小畜之渙 <a class="header-anchor" href="#小畜之渙" aria-label="Permalink to “小畜之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>鶉尾賁賁，火中成軍。虢叔出奔，下失其君。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>《左傳僖五年》：&quot;龍尾伏辰，鶉之賁賁，火中成軍，虢公其奔&quot;，杜註：鶉，鶉火星。尾，尾星。言丙子平旦，鶉火中軍，事有成功也。艮為火、為尾、為星，又為鳥，故曰鶉火、曰鶉尾。賁賁，星體之象。互震為武人，故曰軍。艮手艮虎，故曰虢。《說文》：&quot;虢，虎所攫畫明文也&quot;，艮為少，故曰虢叔。震為奔、為君，坎為失、為下。○艮火證。</p><h3 id="小畜之節" tabindex="-1">小畜之節 <a class="header-anchor" href="#小畜之節" aria-label="Permalink to “小畜之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>兩人相距，止不同舍。夫妻離散，衛侯失居。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>中爻正反艮，故曰相距，正反震，故曰兩人。又兌卦數二，亦兩人象。艮為舍、為止，正反艮，故不同舍。震夫巽妻，巽為風而伏不見，故曰離散。震為諸侯、為衛，故曰衛侯。艮為居，坎陷，故失居。○此用覆象，《易》詞用覆者可解。</p><h3 id="小畜之中孚" tabindex="-1">小畜之中孚 <a class="header-anchor" href="#小畜之中孚" aria-label="Permalink to “小畜之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>魃為旱虐，風吹雲卻。欲止不得，反歸其宅。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮為火，故曰旱虐。震為神，與艮火連體，故曰魃。《詩大雅》：&quot;旱魃為虐&quot;，《毛傳》：&quot;魃，旱神也&quot;。巽為風，兌口為吹，大坎為雲，坎伏，故曰雲卻。卻，退也。艮為止、為宅，震為歸，故曰反歸其宅。○魃、虐，從宋本、汲古。旱，從丁釋文，汲古作災，宋本作燔，元本作魁，為番虎，全訛。</p><h3 id="小畜之小過" tabindex="-1">小畜之小過 <a class="header-anchor" href="#小畜之小過" aria-label="Permalink to “小畜之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>關睢淑女，配我君子。少薑在門，君子嘉喜。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為城關、為鳥，故曰關睢。兌女震善，故曰淑女。艮為君子，兌者，艮妻，故曰配。巽為薑，大過以巽為女妻，故曰少薑。艮為門，震為喜。○少薑，依汲古，宋元本均作少妻，非。妻應作齊。少齊，見《左傳》，巽象也。陳樸園曰：關睢，乃后妃為文王求嬪，據《易林》則是后妃為文王求少薑而得之矣。愚按：文王妃嬪不見有薑氏，武王后邑薑為太公女，安知非為武王求得乎。又《易林》《師》之《坤》說《桃夭》詩雲：男為邦君。陳樸園以為似是武王娶邑薑事，非民間嫁娶，與此正合，此焦詩與毛異處。</p><h3 id="小畜之既濟" tabindex="-1">小畜之既濟 <a class="header-anchor" href="#小畜之既濟" aria-label="Permalink to “小畜之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>慈母赤子，饗賜得士。夷狄服除，以安王家。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《小畜》象。伏坤為母，震子坎赤，故曰赤子。兌為燕饗，震為士，伏坤為夷狄，坤順，故服。震王艮家。○夷狄服除，依宋元本，汲古作降。家，依宋元，與除韻。服除者，言降服掃除之也。</p><h3 id="小畜之未濟" tabindex="-1">小畜之未濟 <a class="header-anchor" href="#小畜之未濟" aria-label="Permalink to “小畜之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>三足孤烏，靈明督郵。司過罰惡，自賊其家，毀敗為憂。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>《漢志》：&quot;日中有三足烏&quot;，《小畜》伏震為足，數三，故曰三足。離為烏，伏坎，故曰孤烏。離為明，坎為賊，艮為家，伏坤為過惡，艮為司，坎為罰。○依《坎》之《渙》校增末句，汲古孤烏訛狐鳴，司訛思，依宋元。家，音姑，與烏韻。丁雲：《漢書尹翁歸傳》：&quot;往署督郵，蓋督察之官&quot;，愚按：《周禮龜人》：&quot;天龜曰靈屬&quot;，《爾雅》：&quot;二曰靈龜。&quot;《古今註》：&quot;龜，一名元衣督郵。&quot;然則靈明督郵謂龜也，與烏同為離象。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
